mapper.select:
SELECT sd.id, sd.main_id, sd.sku_id, sd.sku_no, si.warehouse_org_id AS inventoryOrgId, si.warehouse_org_name AS inventoryOrgName, sd.qty AS salesQty, sd.amount AS salesAmount, sd.is_gift, sd.is_close, sd.remark, si.warehouse_id, sd.currency, sd.currency_symbol FROM so_detail sd INNER JOIN so_info si ON sd.main_id = si.id AND sd.is_deleted = FALSE WHERE si.is_deleted = FALSE AND sd.is_close = FALSE
AND si.id = #{id}
AND sd.sku_no IN
#{skuNo}

SELECT sd.id, sd.main_id, sd.sku_id, sd.sku_no, sd.qty, sd.is_gift, sd.is_close, sd.remark, sd.delivery_status, si.approve_status FROM so_detail sd INNER JOIN so_info si ON sd.main_id = si.id AND sd.is_deleted = FALSE WHERE si.is_deleted=FALSE
AND si.approve_status IN
#{approve}

SELECT sd.id, sd.main_id, sd.sku_id, sd.sku_no, sd.qty, sd.is_gift, sd.is_close, sd.remark, sd.delivery_status, si.approve_status FROM so_detail sd INNER JOIN so_info si ON sd.main_id = si.id AND sd.is_deleted = FALSE WHERE si.is_deleted=FALSE AND si.approve_status='approve'
AND sd.delivery_status IN
#{deliveryStatus}

SELECT sd.id, sd.main_id, sd.sku_id, sd.sku_no, sd.qty, sd.price, sd.tax_rate, sd.amount, sd.currency, sd.currency_symbol, sd.is_gift, sd.is_reissue, sd.is_close, sd.remark, sd.delivery_status, si.approve_status, sd.kingdee_detail_id FROM so_detail sd INNER JOIN so_info si ON sd.main_id = si.id AND sd.is_deleted = FALSE WHERE si.is_deleted = FALSE
AND si.id IN
#{mainId}

SELECT si.approve_status AS type, count(sd.id) FROM so_detail sd INNER JOIN so_info si ON sd.main_id = si.id AND sd.is_deleted = FALSE WHERE si.is_deleted=FALSE
${permissionSql}
GROUP BY si.approve_status

SELECT sd.delivery_status AS type, count(sd.id) FROM so_detail sd INNER JOIN so_info si ON sd.main_id = si.id AND sd.is_deleted = FALSE WHERE si.is_deleted=FALSE AND si.approve_status='approve'
${permissionSql}
GROUP BY sd.delivery_status
